"""Brute‑force solver for the Dominating Set problem defined in problems.py.

The instance format is a dict with keys "n", "edges", and "k".  The function
``solve(instance)`` returns ``True`` iff there exists a dominating set of size
at most ``k``.
"""

from __future__ import annotations

from itertools import combinations
from typing import Dict, List, Set


def solve(instance: Dict) -> bool:
    n: int = instance["n"]
    edges: List[List[int]] = instance["edges"]
    k: int = instance["k"]

    if k < 0:
        return False
    if n == 0:
        return True
    if k >= n:
        return True

    # Build adjacency list including self (dominated by being in set)
    adj: List[Set[int]] = [set() for _ in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    for i in range(n):
        adj[i].add(i)  # a vertex dominates itself

    vertices = list(range(n))
    # Try all subsets of size up to k
    for size in range(k + 1):
        for subset in combinations(vertices, size):
            dominated: Set[int] = set()
            for v in subset:
                dominated.update(adj[v])
            if len(dominated) == n:
                return True
    return False

EOF"}

